import React, { useEffect, useState } from "react";
import { apiDelete, apiGet } from "../utils/api";
import InvoiceTable from "./InvoiceTable";
import InvoiceFilter from "./InvoiceFilter";

const InvoiceIndex = () => {
    const [invoices, setInvoices] = useState([]);
    const [filter, setFilter] = useState({});
    const [buyerList, setBuyerList] = useState([]);
    const [sellerList, setSellerList] = useState([]);

    const deleteInvoice = async (id) => {
        try {
            await apiDelete("/api/invoices/" + id);
        } catch (error) {
            console.log(error.message);
            alert(error.message);
        }
        setInvoices(invoices.filter((item) => item._id !== id));
    };

    const handleFilterChange = (e) => {
        setFilter({ ...filter, [e.target.name]: e.target.value });
    };

    const handleFilterSubmit = (e) => {
        e.preventDefault();

        // Odstranění prázdných hodnot
        const filteredFilter = Object.fromEntries(
            Object.entries(filter).filter(([_, value]) => value !== "")
        );

        const queryParams = new URLSearchParams(filteredFilter).toString();
        const url = queryParams ? `/api/invoices?${queryParams}` : "/api/invoices";

        console.log("Fetching data from:", url); // Logování URL dotazu

        apiGet(url).then((data) => {
            console.log("Received data:", data); // Logování odpovědi z API
            setInvoices(data);
        }).catch((error) => {
            console.error("API request error:", error); // Logování chyby
        });
    };



    useEffect(() => {
        apiGet("/api/invoices").then((data) => setInvoices(data));
        apiGet("/api/persons").then(setSellerList);
        apiGet("/api/persons").then(setBuyerList);
    }, []);

    return (
        <div>
            <h1>Seznam faktur</h1>
            <InvoiceFilter
                filter={filter}
                handleChange={handleFilterChange}
                handleSubmit={handleFilterSubmit}
                confirm="Filtrovat"
                buyerList={buyerList}
                sellerList={sellerList}
            />
            <InvoiceTable deleteInvoice={deleteInvoice} items={invoices} label="Počet faktur:" />
        </div>
    );
};

export default InvoiceIndex;
